CREATE TABLE IF NOT EXISTS admins (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, hash_iterations INTEGER NOT NULL DEFAULT 100000, admin_level TEXT NOT NULL DEFAULT 'SUPER', created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS students (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, salt TEXT NOT NULL, hash_iterations INTEGER NOT NULL DEFAULT 100000, department TEXT NOT NULL, year_of_study INTEGER NOT NULL, interests TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS clubs (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, category TEXT NOT NULL, description TEXT, contact_email TEXT, contact_info TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, description TEXT, category TEXT NOT NULL, opportunity_type TEXT NOT NULL, event_date TEXT NOT NULL, venue TEXT NOT NULL, organizer TEXT NOT NULL, reg_deadline TEXT, eligibility TEXT DEFAULT 'All Students', capacity INTEGER NOT NULL DEFAULT 50, available_seats INTEGER NOT NULL DEFAULT 50, registration_open INTEGER NOT NULL DEFAULT 1, active INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS registrations (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, reg_date TEXT DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'REGISTERED', attendance_status TEXT NOT NULL DEFAULT 'PENDING', verified_at TEXT, verified_by TEXT, UNIQUE (student_id, event_id));
CREATE TABLE IF NOT EXISTS saved_events (student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, event_id INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE, saved_at TEXT DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (student_id, event_id));
